import sys,json,html,csv,xml.etree.ElementTree as ET
from pathlib import Path
from shapely.geometry import shape
from shapely import transform as transform_coords
def transform(project,g): return transform_coords(g,project,interleaved=False)
from pyproj import Transformer
r=Path(__file__).resolve().parents[1];q=json.loads((r/'data/audits/2026-10-29-geometry-qc.json').read_text());b=json.loads((r/'3d/data/buildings.geojson').read_text());l=json.loads((r/'3d/data/landmarks.geojson').read_text());quality=r/'quality';quality.mkdir(exist_ok=True)
flagged={s for pair in q['overlaps'] for s in pair['source_ids']}
for f in b['features']:f['properties']['topology_review']=f['properties']['source_id'] in flagged
(r/'3d/data/buildings.geojson').write_text(json.dumps(b,ensure_ascii=False,separators=(',',':')))
# Summary excludes the full building index; the complete report remains downloadable.
summary={k:v for k,v in q.items() if k!='buildings'};summary['building_count']=len(b['features']);summary['overlap_pairs']=len(q['overlaps']);summary['overlap_buildings']=len(flagged);summary['original_osm_building_count']=146;summary['original_osm_place_pins_in_footprint']=2
(r/'3d/data/qc.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
with (quality/'landmark-review.csv').open('w',encoding='utf-8-sig',newline='') as fh:
 w=csv.writer(fh);w.writerow(['number','name','longitude','latitude','role','candidate_source_id','candidate_dataset','distance_to_edge_m_NOT_accuracy','point_in_footprint_NOT_identity','entrance_verified','height_verified','surveyor','survey_date','field_lat','field_lon','measured_height_m','evidence_url'])
 for row in q['landmarks']:
  c=row['candidates'][0];w.writerow([row['number'],row['name'],*row['coordinates'],row['role'],c['source_id'],c['source_dataset'],c['distance_to_footprint_m'],c['point_inside_footprint'],False,False,'','','','','',''])
# KML retains footprint location only; unknown heights are not extruded.
ns='http://www.opengis.net/kml/2.2';ET.register_namespace('',ns)
def node(parent,tag,text=None):
 el=ET.SubElement(parent,'{'+ns+'}'+tag)
 if text is not None:el.text=str(text)
 return el
k=ET.Element('{'+ns+'}kml');doc=node(k,'Document');node(doc,'name','ศรีจันทร์ — ตรวจขอบอาคารและหมุด ไม่รับรองความสูง');folder=node(doc,'Folder');node(folder,'name','17 หมุดอ้างอิง')
for f in l['features']:
 p=node(folder,'Placemark');node(p,'name',f['properties']['name']);node(p,'description',f['properties'].get('position_status','')+'; อาคาร/ทางเข้า/ความสูงยังไม่ผ่านตรวจภาคสนาม');pt=node(p,'Point');node(pt,'altitudeMode','clampToGround');node(pt,'coordinates',','.join(map(str,f['geometry']['coordinates'])))
folder=node(doc,'Folder');node(folder,'name','ขอบอาคาร OSM + Overture (ไม่ยกความสูง)')
for f in b['features']:
 p=node(folder,'Placemark');pr=f['properties'];node(p,'name',pr['name']);node(p,'description',pr['source_dataset']+'; '+pr['source_url']+'; ยังไม่ยืนยันความสูง');poly=node(p,'Polygon');node(poly,'altitudeMode','clampToGround');outer=node(poly,'outerBoundaryIs');ring=node(outer,'LinearRing');node(ring,'coordinates',' '.join(','.join(map(str,c)) for c in f['geometry']['coordinates'][0]))
ET.ElementTree(k).write(quality/'srichan-gis-review.kml',encoding='utf-8',xml_declaration=True)
# North-up UTM inspection drawing. All paths and landmark points use the same transformation.
proj=Transformer.from_crs(4326,32648,always_xy=True).transform;gs=[transform(proj,shape(f['geometry'])) for f in b['features']];pts=[proj(*f['geometry']['coordinates']) for f in l['features']];xmin=min(g.bounds[0] for g in gs);ymax=max(g.bounds[3] for g in gs);width=max(g.bounds[2] for g in gs)-xmin;height=ymax-min(g.bounds[1] for g in gs)
def coords(c):return f'{c[0]-xmin:.2f},{ymax-c[1]:.2f}'
paths=[]
for f,g in zip(b['features'],gs):
 pr=f['properties'];color='#bb6a2c' if pr['topology_review'] else '#52768a' if pr['source_dataset']=='OpenStreetMap' else '#a8afb1'
 paths.append(f'<polygon points="{" ".join(coords(c) for c in g.exterior.coords)}" fill="{color}" fill-opacity=".36" stroke="{color}" stroke-width=".6"><title>{html.escape(pr["source_id"]+" · "+pr["source_dataset"])}</title></polygon>')
markers=[];rows=[]
(quality/'candidates').mkdir(exist_ok=True)
building_index={f['properties']['source_id']:f for f in b['features']}
for row,p in zip(q['landmarks'],pts):
 n=row['number'];c=row['candidates'][0];(quality/'candidates'/f'{n:02d}.geojson').write_text(json.dumps({'type':'FeatureCollection','features':[building_index[c['source_id']]],'note':'อาคารใกล้สุดเป็นเพียงตัวเลือกตรวจสอบ ไม่ใช่การยืนยันว่าเป็นสถานที่เดียวกัน'},ensure_ascii=False,indent=2));x=p[0]-xmin;y=ymax-p[1];color='#b45b22' if row['role']=='photo_viewpoint' else '#173b62'
 markers.append(f'<g class="pin" data-n="{n}" transform="translate({x:.2f} {y:.2f})"><circle r="5" fill="{color}"/><text text-anchor="middle" x="8" y="-6" fill="#173b62" font-size="12">{n}</text></g>')
 result='หมุดอยู่ในขอบอาคาร' if c['point_inside_footprint'] else f'ห่างขอบใกล้สุด {c["distance_to_footprint_m"]:.2f} ม.'
 rows.append(f'<tr><td><button data-focus="{x:.2f},{y:.2f}" data-name="{html.escape(row["name"],quote=True)}">{n}</button></td><td>{html.escape(row["name"])}<small>{"จุดชมมุมภาพโดยประมาณ" if row["role"]=="photo_viewpoint" else "หมุดอ้างอิงสถานที่"}</small></td><td>{result}<small>{html.escape(c["source_dataset"])}</small></td><td>ยังไม่ยืนยัน<small>อาคาร · ทางเข้า · ความสูง</small></td><td><a target="_blank" rel="noopener" href="candidates/{n:02d}.geojson">ขอบอาคารผู้สมัคร GeoJSON ↗</a></td></tr>')
counts={};
for f in b['features']:counts[f['properties']['source_dataset']]=counts.get(f['properties']['source_dataset'],0)+1
page=f'''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ตรวจ GIS ศรีจันทร์ — ขอบอาคารและ 17 หมุด</title><style>body{{font:16px system-ui;margin:0;background:#f4efe4;color:#173b62}}main{{max-width:1250px;margin:auto;padding:24px}}h1{{font-size:30px}}p{{line-height:1.7}}.notice{{padding:18px;background:#fff1db;border-left:5px solid #b45b22}}.stats{{display:flex;gap:14px;flex-wrap:wrap}}.stats div{{background:white;padding:16px;border-radius:10px}}strong{{font-size:26px}}svg{{width:100%;height:520px;background:#faf8f1;border:1px solid #ccc}}.mapbar{{display:flex;gap:12px;align-items:center;margin:15px 0}}button{{cursor:pointer;border:1px solid #bbb;padding:9px;border-radius:6px;background:white;color:#173b62}}table{{width:100%;border-collapse:collapse;background:white}}td,th{{text-align:left;padding:12px;border-bottom:1px solid #ddd;vertical-align:top}}small{{display:block;color:#556675;margin-top:5px}}a{{color:#a34b16}}.scroll{{overflow:auto}}.pin{{pointer-events:none}}@media(max-width:650px){{svg{{height:360px}}h1{{font-size:24px}}td,th{{padding:8px}}}}</style><main><a href="../join/">← หน้าแผนที่โครงการ</a><h1>ตรวจ GIS: ขอบอาคารและ 17 หมุดศรีจันทร์</h1><p>ตรวจเมื่อ 29 ตุลาคม 2569 · แผนที่เพื่อสำรวจและวางแนวคิด</p><p class="notice"><b>ยังไม่ผ่านการตรวจรับความแม่นยำภาคสนาม</b><br>หมุดตรงกับรายการ Google Maps ไม่ได้แปลว่าตัวอาคาร ทางเข้าหรือความสูงถูกต้อง การอยู่ในขอบอาคารเป็นเพียงผลตรวจเชิงรูปทรง ห้ามใช้ระยะห่างขอบเป็นค่าความแม่นยำ ไม่มีจุดตรวจอิสระจากงานสำรวจ จึงยังไม่มีค่า RMSE หรือใบรับรองความถูกต้อง</p><div class="stats"><div><strong>{len(b['features']):,}</strong><br>ขอบอาคารข้อมูลเปิด</div><div><strong>{sum(r['candidates'][0]['point_inside_footprint'] for r in q['landmarks'])}/17</strong><br>หมุดอยู่ในขอบอาคาร</div><div><strong>{q['height_unknown_count']:,}</strong><br>ไม่ทราบความสูง</div><div><strong>{len(q['overlaps'])}</strong><br>คู่ขอบอาคารทับกัน &gt; 1 ตร.ม. รอตรวจ</div></div><p>แก้ช่องว่างจาก OSM เดิม 146 ขอบอาคาร โดยเพิ่มข้อมูล Overture รุ่น 2026-10-21.0 รวมแหล่งข้อมูล {html.escape('OSM '+str(counts.get('OpenStreetMap',0))+' / Microsoft '+str(counts.get('Microsoft ML Buildings',0))+' / Google Open Buildings '+str(counts.get('Google Open Buildings',0)))} รักษา OSM เดิมเมื่อขอบทับกัน และไม่ย้ายหมุดไปอาคารใกล้สุดโดยอัตโนมัติ ข้อมูลตรวจจับอาคารยังอาจผิดหรือเก่าได้</p><div class="mapbar"><button id="reset">มองทั้งย่าน</button><span id="selected">เหนืออยู่ด้านบน · UTM 48N · กดหมายเลขในตารางเพื่อขยาย</span></div><svg id="qcmap" viewBox="0 0 {width:.2f} {height:.2f}" role="img" aria-label="แผนผังตรวจขอบอาคาร 2524 รูปทรงและหมุด 17 จุด ทางเหนืออยู่ด้านบน"><title>ผังตรวจตำแหน่งอาคารและหมุด ใช้พิกัดเมตร UTM โซน 48 เหนือ</title>{''.join(paths)}{''.join(markers)}</svg><p>น้ำเงิน: OSM · เทา: ขอบจากข้อมูลเปิดอื่น · ส้ม: ขอบที่มีการทับกันต้องตรวจ · หมุดส้ม: บริเวณชมมุมภาพ<br>ไม่มีภาพฐานในผังนี้ ใช้เพื่อตรวจความสัมพันธ์ของข้อมูล ไม่ใช้แทนภาพถ่ายจริง</p><div class="scroll"><table><thead><tr><th>จุด</th><th>สถานที่</th><th>ผลตรวจเชิงรูปทรง</th><th>สถานะตรวจรับ</th><th>ต้นทาง</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><h2>งานที่ต้องทำก่อนยืนยันว่าตรงภาพจริง</h2><ol><li>เทียบภาพตั้งฉากที่ทราบวันที่และการอ้างอิงพิกัด ตรวจฐานอาคาร ไม่ใช้ยอดหลังคาหรือภาพ AI เป็นหลักฐานรังวัด</li><li>ให้ชุมชนยืนยันว่าอาคารเดียวกับชื่อสถานที่ และระบุทางเข้าที่ใช้งานจริง</li><li>สำรวจจุดอ้างอิงอิสระด้วย GNSS/RTK หรือวิธีสำรวจที่เหมาะกับความแม่นยำที่โครงการต้องการ บันทึกเครื่องมือ วัน ระบบพิกัดและความไม่แน่นอน</li><li>วัดความสูงหรือจำนวนชั้นที่ยืนยันได้ และแยกความสูงจำลองออกจากค่าที่วัด</li><li>สำหรับ 7 จุดมุมภาพ บันทึกจุดยืน ทิศกล้อง และภาพถ่ายจริงอีกครั้ง ไม่ขยับหมุดเข้าหาอาคารอัตโนมัติ</li></ol><p><a href="landmark-review.csv">ดาวน์โหลดตารางตรวจภาคสนาม CSV</a> · <a href="srichan-gis-review.kml">KML ตรวจเทียบใน Google Earth / QGIS</a> · <a href="../data/audits/2026-10-29-geometry-qc.json">ผลตรวจ GIS ฉบับข้อมูล</a></p><h2>แหล่งข้อมูลและวิธีทำงาน</h2><p>พิกัดต้นทาง WGS84 EPSG:4326 ลำดับ longitude, latitude · ระยะ/พื้นที่คำนวณ UTM โซน 48N EPSG:32648 ด้วย Shapely และ pyproj · ตรวจวงปิด รูปทรงใช้ได้ และการทับกัน · ไม่อ้างว่าเป็นการรับรองตามมาตรฐาน ASPRS</p><p><a href="https://www.fgdc.gov/csdgmgraphical/dataq/posaccfq.htm">FGDC: การรายงานคุณภาพตำแหน่งและแหล่งตรวจอิสระ</a> · <a href="https://docs.overturemaps.org/attribution/">Overture: ต้นทางและสิทธิข้อมูล</a> · <a href="https://wiki.openstreetmap.org/wiki/Key:building:levels">OSM: จำนวนชั้นไม่ใช่ความสูงรังวัด</a></p><p>© OpenStreetMap contributors, Overture Maps Foundation · Microsoft ML Buildings (ODbL) · Google Open Buildings (CC BY 4.0) · ข้อมูลอาคารรวมเผยแพร่ภายใต้ ODbL</p></main><script>const map=document.getElementById('qcmap'),full=map.getAttribute('viewBox');const size=(zoom)=>document.querySelectorAll('.pin').forEach(g=>{{g.querySelector('circle').setAttribute('r',zoom?'0.9':'5');const t=g.querySelector('text');t.setAttribute('font-size',zoom?'2.5':'12');t.setAttribute('x',zoom?'2':'8');t.setAttribute('y',zoom?'-2':'-6')}});document.getElementById('reset').onclick=()=>{{size(false);map.setAttribute('viewBox',full);document.getElementById('selected').textContent='เหนืออยู่ด้านบน · UTM 48N'}};document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{{const [x,y]=b.dataset.focus.split(',').map(Number);size(true);map.setAttribute('viewBox',`${{x-100}} ${{y-75}} 200 150`);document.getElementById('selected').textContent=b.dataset.name+' · ช่องมอง 200 × 150 เมตร';map.scrollIntoView({{behavior:'smooth',block:'center'}})}});</script></html>'''
(quality/'index.html').write_text(page)
